!function(){"use strict";var joinchat=document.querySelector('.joinchat');if(!joinchat)return;var button=joinchat.querySelector('.joinchat__button');var chatbox=joinchat.querySelector('.joinchat__chatbox');var closeBtn=joinchat.querySelector('.joinchat__close');var settings=JSON.parse(joinchat.dataset.settings||'{}');var phone=settings.telephone||'';var message=settings.message_send||'';setTimeout(function(){joinchat.removeAttribute('hidden');joinchat.setAttribute('aria-hidden','false')},settings.button_delay*1000||3000);button.addEventListener('click',function(e){e.preventDefault();var url='https://wa.me/'+phone;if(message){url+='?text='+encodeURIComponent(message)}window.open(url,'_blank')});if(closeBtn){closeBtn.addEventListener('click',function(e){e.preventDefault();if(chatbox){chatbox.setAttribute('aria-hidden','true')}})}}();
